          "document_id": "migrated-tenant-page-document:migrated-tenant-page-variant:page_ncls_home:en",
          "snapshot_json": "{\"schemaVersion\":1,\"metadata\":{\"locale\":\"en\",\"path\":\"/\",\"title\":\"Access to Justice for All. North Carolina's affordable legal services.\",\"summary\":\"\",\"seoTitle\":null,\"seoDescription\":null,\"canonicalUrl\":null,\"robots\":null,\"pageType\":\"system\",\"recipe\":null},\"blocks\":[{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:0\",\"parent_block_id\":null,\"type\":\"hero\",\"position\":0,\"level\":null,\"data\":{\"title\":\"Access to Justice for All.\\nNorth Carolina's affordable\\nlegal services.\",\"accent\":\"Justice for All.\",\"description\":\"We believe that access to the Justice System is a fundamental right. At North Carolina Legal Services we are committed to removing financial barriers that prevent many in our community from obtaining high-quality legal assistance.\",\"label\":\"Request a Consultation\",\"url\":\"/schedule\",\"background\":{\"asset_id\":\"asset_ncls_media_background-hero_05f81e86\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/599abbcd10dd490792d2.webp\",\"role\":\"home_hero_background\",\"source_name\":\"background-hero.webp\"},\"section\":\"hero\",\"cta_label\":\"Request a Consultation\",\"cta_url\":\"/schedule\",\"asset_id\":\"asset_ncls_media_background-hero_05f81e86\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:1\",\"parent_block_id\":null,\"type\":\"offering_grid\",\"position\":1,\"level\":null,\"data\":{\"title\":\"Our\",\"accent\":\"Services\",\"description\":\"Explore a wide range of legal services provided by North Carolina Legal Services. Our dedicated team offers expert assistance in Family Law, Small Business Legal Support, Employment Law, Tenant Rights Law, and Probate & Estate Planning. Find the legal support you need to protect your rights and secure your future.\",\"decoration\":{\"asset_id\":\"asset_ncls_media_background-features_d3572b1b\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/be87d08d6e14bf57ecef.webp\",\"role\":\"services_background\",\"source_name\":\"background-features.webp\"},\"source\":\"site_offerings\",\"section\":\"services\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:2\",\"parent_block_id\":null,\"type\":\"feature_grid\",\"position\":2,\"level\":null,\"data\":{\"title\":\"Empowering North Carolina: Our Innovative\",\"accent\":\"Approach to Justice\",\"video_url\":\"https://www.youtube.com/embed/glBHONAzWYo?si=coXUD5UlzMHAfzVD\",\"video_title\":\"Rich Gittings Speaks about North Carolina Legal Services\",\"images\":[{\"asset_id\":\"asset_ncls_media_getting-a-divorce-in-north-carolina_ffbfbfd0\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/ea4d301a3cefbbd17a44.webp\",\"role\":\"approach_supporting_image\",\"source_name\":\"getting_a_divorce_in_north_carolina.webp\"},{\"asset_id\":\"asset_ncls_media_writing-your-own-will-how-it-works_c1f1ad9b\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/6b9b810084d4809b6d5d.webp\",\"role\":\"approach_supporting_image\",\"source_name\":\"writing-your-own-will-how-it-works.webp\"}],\"items\":[{\"title\":\"Accessible Justice\",\"description\":\"North Carolina Legal Services introduces a groundbreaking approach to legal aid, ensuring justice is within reach for all. Our sliding scale fee system, based on income, guarantees affordability without compromising quality representation.\"},{\"title\":\"Expert Attorneys\",\"description\":\"Our team comprises seasoned attorneys committed to swift and efficient service. With tight budgets in mind, our attorneys prioritize quick turnaround times, ensuring every client receives the attention they deserve.\"},{\"title\":\"Flexible Scheduling\",\"description\":\"At North Carolina Legal Services, flexibility is key. Attorneys have the freedom to set their own schedules, ensuring work-life balance without sacrificing client needs. It's a stress-free environment where both judges and clients are satisfied.\"},{\"title\":\"Supportive Environment\",\"description\":\"Join a team where support is abundant. Whether it's assistance with cases or guidance on legal matters, North Carolina Legal Services fosters a supportive atmosphere, allowing attorneys to thrive and deliver exceptional results.\"}],\"section\":\"approach\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:3\",\"parent_block_id\":null,\"type\":\"faq\",\"position\":3,\"level\":null,\"data\":{\"decoration\":{\"asset_id\":\"asset_ncls_media_background-feature-2_970a5c32\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/c53c7b8d7a6de1e7cc70.webp\",\"role\":\"qa_background\",\"source_name\":\"background-feature-2.webp\"},\"source\":\"page_qa\",\"section\":\"qa\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:4\",\"parent_block_id\":null,\"type\":\"testimonial_grid\",\"position\":4,\"level\":null,\"data\":{\"title\":\"What Clients Say\",\"description\":\"At North Carolina Legal Services we believe that access to the justice system shouldn't be limited by one's income. We offer quality legal services at a price that working families can afford.\",\"source\":\"site_reviews\",\"section\":\"reviews\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:articles\",\"parent_block_id\":null,\"type\":\"feature_grid\",\"position\":5,\"level\":null,\"data\":{\"title\":\"From the Blog\",\"source\":\"site_posts\",\"limit\":3,\"section\":\"articles\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:articles-more\",\"parent_block_id\":null,\"type\":\"button_group\",\"position\":6,\"level\":null,\"data\":{\"buttons\":[{\"label\":\"See All\",\"url\":\"/blog\"}],\"section\":\"articles-more\"}},{\"id\":\"migrated-tenant-page-block:migrated-tenant-page-variant:page_ncls_home:en:component:6\",\"parent_block_id\":null,\"type\":\"contact_cta\",\"position\":7,\"level\":null,\"data\":{\"title\":\"Get started today\",\"accent\":\"today\",\"description\":\"Trust our friendly team for affordable, comprehensive legal services. Contact us today to resolve your legal issues and gain peace of mind.\",\"label\":\"Request a Consultation\",\"url\":\"/schedule\",\"background\":{\"asset_id\":\"asset_ncls_media_background-cta_79bdbc52\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/735d1ec58bf43ca897ce.webp\",\"role\":\"consultation_cta_background\",\"source_name\":\"background-cta.webp\"},\"featured\":{\"asset_id\":\"asset_ncls_media_logo-2_e3a91ed9\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/9cb15d96c31f5ba5fb2c.webp\",\"role\":\"consultation_cta_featured\",\"source_name\":\"logo-2.webp\"},\"section\":\"consultation\"}}]}",
