          "parent_block_id": null,
          "type": "contact_cta",
          "position": 6,
          "level": null,
          "data_json": "{\"title\":\"Get started today\",\"accent\":\"today\",\"description\":\"Trust our friendly team for affordable, comprehensive legal services. Contact us today to resolve your legal issues and gain peace of mind.\",\"label\":\"Request a Consultation\",\"url\":\"/schedule\",\"background\":{\"asset_id\":\"asset_ncls_media_background-cta_79bdbc52\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/735d1ec58bf43ca897ce.webp\",\"role\":\"consultation_cta_background\",\"source_name\":\"background-cta.webp\"},\"featured\":{\"asset_id\":\"asset_ncls_media_logo-2_e3a91ed9\",\"url\":\"https://media.krabiclaw.com/sites/site-ncls-blawby/media/imports/9cb15d96c31f5ba5fb2c.webp\",\"role\":\"consultation_cta_featured\",\"source_name\":\"logo-2.webp\"},\"section\":\"consultation\"}",
